package scan

import "github.com/anthnel/devdesk/internal/config"

// OptionsFromConfig builds the scan options a context is configured with.
//
// This is the only way ScanOptions is assembled. Three call sites used to do it
// by hand — the security form, the workspaces list and the images list — and
// they had drifted: only the form set IgnoreEOL, so the option applied when
// scanning from the form and silently did not from either list (D26).
//
// OnProgress is deliberately left nil: it is per-scan wiring, not configuration,
// and belongs to whoever starts the scan. So is LoadForgeToken, which needs the
// context's secret store — the caller has it, this function does not.
//
// It takes the whole Config rather than its Scan section because the CI stage
// needs the forge: which platform a context targets is what decides whether a
// repository is graded at all (§3.42), and that is not a scan setting.
func OptionsFromConfig(cfg *config.Config) ScanOptions {
	c := cfg.Scan
	// The address is kept in the config even when the checkbox is off, so
	// switching it back on does not lose what was typed — but a scan must not
	// see it until the checkbox says client-server mode is wanted.
	trivyServer := ""
	if c.UseTrivyServer {
		trivyServer = c.TrivyServer
	}
	return ScanOptions{
		EnableCIScore:   c.EnableCIScore,
		PlumberSource:   c.PlumberSource,
		PlumberPath:     c.PlumberPath,
		PlumberImage:    c.PlumberImage,
		PlumberConfig:   c.PlumberConfig,
		Forge:           cfg.Forge,
		EnableVuln:      c.EnableVuln,
		EnableSecret:    c.EnableSecret,
		EnableLicense:   c.EnableLicense,
		EnableMisconfig: c.EnableMisconfig,
		TrivySource:     c.TrivySource,
		TrivyPath:       c.TrivyPath,
		TrivyImage:      c.TrivyImage,
		GitleaksSource:  c.GitleaksSource,
		GitleaksPath:    c.GitleaksPath,
		GitleaksImage:   c.GitleaksImage,
		TrivyServer:     trivyServer,
		IgnoreUnfixed:   c.IgnoreUnfixed,
		IgnoreEOL:       c.IgnoreEOL,
		GitleaksHistory: c.GitleaksHistory,
		GitleaksConfig:  c.GitleaksConfig,
	}
}

// ScanOptions configures which scanners to run
type ScanOptions struct {
	EnableVuln      bool   // Vulnerability scanning (Trivy)
	EnableSecret    bool   // Secret scanning (Gitleaks)
	EnableLicense   bool   // License scanning (Trivy)
	EnableMisconfig bool   // Misconfiguration scanning (Trivy)
	TrivySource     string // Where Trivy runs from: auto | binary | image
	TrivyPath       string // Custom Trivy executable (optional)
	TrivyImage      string // Custom Docker image for Trivy (optional)
	GitleaksSource  string // Where Gitleaks runs from: auto | binary | image
	GitleaksPath    string // Custom Gitleaks executable (optional)
	GitleaksImage   string // Custom Docker image for Gitleaks (optional)
	TrivyServer     string // Trivy server URL for client-server mode (optional)
	IgnoreUnfixed   bool   // Trivy: only show vulnerabilities with fixes
	IgnoreEOL       bool   // Trivy: ignore end-of-life package vulnerabilities (--ignore-status end_of_life)
	GitleaksHistory bool   // Gitleaks: scan git history (omit --no-git)
	GitleaksConfig  string // Gitleaks: custom config file path

	// EnableCIScore runs plumber over the repository's CI configuration.
	EnableCIScore bool
	// PlumberSource, PlumberPath, PlumberImage, PlumberConfig mirror the other
	// two tools.
	PlumberSource string
	PlumberPath   string
	PlumberImage  string
	PlumberConfig string

	// Forge is the platform this context targets, and it is what decides
	// whether a repository is graded at all: a GitHub context grades its GitHub
	// repositories and nothing else (§3.42). The scan resolves that per target
	// rather than per batch, because one batch holds repositories with
	// different remotes.
	Forge config.ForgeConfig
	// LoadForgeToken is called only for a repository whose remote is the
	// configured forge, so one of another host never reaches the secret store.
	// It runs on a scan goroutine, like the clone's tokenLoader.
	LoadForgeToken func() string
	// OnProgress is an optional callback invoked at each stage transition.
	// It is called from scan goroutines; implementations must be thread-safe.
	OnProgress func(ProgressUpdate)
}

// Finding represents a single security finding
type Finding struct {
	ID          string        `json:"id"`
	expand := func(path string) string {
		if strings.HasPrefix(path, "~/") {
			return filepath.Join(homeDir, path[2:])
		}
		return path
	}

	c.App.LogFile = expand(c.App.LogFile)
	c.App.WorkspacesDir = expand(c.App.WorkspacesDir)
	c.Registry.CacheDir = expand(c.Registry.CacheDir)
	c.Scan.CacheDir = expand(c.Scan.CacheDir)
	c.Scan.TrivyPath = expand(c.Scan.TrivyPath)
	c.Scan.GitleaksPath = expand(c.Scan.GitleaksPath)
	c.Scan.GitleaksConfig = absolute(expand(c.Scan.GitleaksConfig))
	c.Scan.PlumberConfig = absolute(expand(c.Scan.PlumberConfig))
}

